langs = ["values", "values-te", "values-ta", "values-kn", "values-ml", "values-zh"]

def escape_xml(s):
    return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("'", "\\'")

for idx, lang in enumerate(langs):
    dir_path = f"app/src/main/res/{lang}"
    os.makedirs(dir_path, exist_ok=True)
    with open(f"{dir_path}/strings.xml", "w") as f:
        f.write('<?xml version="1.0" encoding="utf-8"?>\n<resources>\n')
        for key, vals in strings.items():
            f.write(f'    <string name="{key}">{escape_xml(vals[idx])}</string>\n')
        f.write('</resources>\n')
